//! The tokenizer must produce exactly the tokens and errors of the original
//! hand-rolled state machine, for every short line over the format's
//! significant characters.
#[path = "support/oracle.rs"]
mod oracle;

use logscan::{tokenize, LexError, Token};

const ALPHABET: &[u8] = b"[]\"=\\n a\t";
const MAX_LEN: usize = 7;

fn run<'a, I: Iterator<Item = Result<Token<'a>, LexError>>>(it: I) -> Vec<Result<Token<'a>, LexError>> {
    it.collect()
}

#[test]
fn matches_the_original_on_every_short_line() {
    let mut buf = Vec::new();
    let mut checked = 0u64;
    for len in 0..=MAX_LEN {
        let total = ALPHABET.len().pow(len as u32);
        for mut code in 0..total {
            buf.clear();
            for _ in 0..len {
                buf.push(ALPHABET[code % ALPHABET.len()]);
                code /= ALPHABET.len();
            }
            let line = std::str::from_utf8(&buf).unwrap();
            assert_eq!(run(tokenize(line)), run(oracle::Oracle::new(line)), "line {line:?}");
            checked += 1;
        }
    }
    assert!(checked > 5_000_000);
}
