/// Where the tokenizer is within a line.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    /// Before a timestamp, key or word; blanks may precede it.
    Start,
    /// Right after a `key=`; a value (possibly empty) comes next.
    Value,
    /// An error was reported; nothing more is yielded.
    Failed,
}

/// What a scanner produced: the token and the offset just past it.
type Scan<'a> = Result<(Token<'a>, usize), LexError>;

/// Streams the tokens of one line. After the first error it yields nothing more.
#[derive(Debug, Clone)]
pub struct Tokens<'a> {
    src: &'a str,
    pos: usize,
    state: State,
}

impl<'a> Tokens<'a> {
    pub fn new(src: &'a str) -> Self {
        Tokens { src, pos: 0, state: State::Start }
    }
}

/// Tokenizes one log line without copying any of it.
pub fn tokenize(line: &str) -> Tokens<'_> {
    Tokens::new(line)
}

impl<'a> Iterator for Tokens<'a> {
    type Item = Result<Token<'a>, LexError>;

    fn next(&mut self) -> Option<Self::Item> {
        let src = self.src;
        let scan = match self.state {
            State::Start => {
                let start = skip_blanks(src.as_bytes(), self.pos);
                if start >= src.len() {
                    self.pos = start;
                    return None;
                }
                scan_start(src, start)
            }
            State::Value => scan_value(src, self.pos),
            State::Failed => return None,
        };
        Some(match scan {
            Ok((token, end)) => {
                self.pos = end;
                self.state = match token {
                    Token::Key(_) => State::Value,
                    _ => State::Start,
                };
                Ok(token)
            }
            Err(error) => {
                self.pos = src.len();
                self.state = State::Failed;
                Err(error)
            }
        })
    }
}

fn is_blank(c: u8) -> bool {
    c == b' ' || c == b'\t'
}

fn skip_blanks(b: &[u8], mut p: usize) -> usize {
    while p < b.len() && is_blank(b[p]) {
        p += 1;
    }
    p
}

/// A token that ends at `end` must be followed by a blank or the end of the line.
fn expect_separator(b: &[u8], end: usize) -> Result<(), LexError> {
    match b.get(end) {
        Some(&c) if !is_blank(c) => Err(LexError::ExpectedSeparator { pos: end }),
        _ => Ok(()),
    }
}

/// Scans a token at `p`, which is not blank and not past the end.
fn scan_start(src: &str, p: usize) -> Scan<'_> {
    match src.as_bytes()[p] {
        b'[' => scan_timestamp(src, p),
        b'"' => Err(LexError::UnexpectedQuote { pos: p }),
        b'=' => Err(LexError::EmptyKey { pos: p }),
        _ => scan_key_or_word(src, p),
    }
}

/// `[` text `]`, where `p` is at the `[`.
fn scan_timestamp(src: &str, p: usize) -> Scan<'_> {
    let b = src.as_bytes();
    let start = p + 1;
    for (i, &c) in b.iter().enumerate().skip(start) {
        match c {
            b']' => {
                expect_separator(b, i + 1)?;
                return Ok((Token::Timestamp(&src[start..i]), i + 1));
            }
            b'[' => return Err(LexError::NestedBracket { pos: i }),
            _ => {}
        }
    }
    Err(LexError::UnterminatedTimestamp { pos: p })
