fn main() {
    let mut lines = Vec::new();
    for i in 0..200_000 {
        lines.push(format!("[2024-05-01T12:00:{:02}Z] level=info msg=\"request {} took \\\"{}\\\" ms\\n\" user=ann{} path=/api/v1/items/{} status=200 empty= worker-3 ok", i % 60, i, i % 977, i % 13, i));
        if i % 50 == 0 { lines.push(format!("[2024-05-01 bad line {} msg=\"never closed", i)); }
    }
    let bytes: usize = lines.iter().map(|l| l.len()).sum();
    for round in 0..4 {
        let t = Instant::now(); let mut a = 0;
        for _ in 0..10 { for l in &lines { a += count!(old, l); } }
        let o = t.elapsed();
        let t = Instant::now(); let mut b = 0;
        for _ in 0..10 { for l in &lines { b += count!(new, l); } }
        let n = t.elapsed();
        assert_eq!(a, b);
        println!("round {round}: old {:?} new {:?} ({:.0} vs {:.0} MB/s)", o, n,
            10.0*bytes as f64/o.as_secs_f64()/1e6, 10.0*bytes as f64/n.as_secs_f64()/1e6);
    }
}
